  // 获取服务器列表
  getServerList() {
    return request.get(`${config.API_VERSION}/servers`);
  },
  // 启动服务器
  startServer(id) {
    return request.post(`${config.API_VERSION}/servers/${id}/start`);
  },
  // 停止服务器
  stopServer(id) {
    return request.post(`${config.API_VERSION}/servers/${id}/stop`);
  },
  // 重启服务器
  restartServer(id) {
    return request.post(`${config.API_VERSION}/servers/${id}/restart`);
  },
  // 获取服务器配置
