    return request.get(`${config.API_VERSION}/servers/${id}/config`);
  },
  // 更新服务器配置
  updateServerConfig(id, data) {
    return request.put(`${config.API_VERSION}/servers/${id}/config`, data);
  }
};

// 房间相关API
