    return request.post(`${config.API_VERSION}/players/${id}/ban`, data);
  },
  // 发送消息给玩家
  sendMessage(id, data) {
    return request.post(`${config.API_VERSION}/players/${id}/message`, data);
  }
};

// 模组相关API
export const modApi = {
  // 获取模组列表
  getModList() {
    return request.get(`${config.API_VERSION}/mods`);
  },
  // 安装模组
  installMod(data) {
    return request.post(`${config.API_VERSION}/mods/install`, data);
  },
  // 卸载模组
  uninstallMod(id) {
    return request.post(`${config.API_VERSION}/mods/${id}/uninstall`);
  },
  // 更新模组
  updateMod(id) {
    return request.post(`${config.API_VERSION}/mods/${id}/update`);
  }
};

// 系统相关API
export const systemApi = {
  // 获取系统信息
  getSystemInfo() {
    return request.get(`${config.API_VERSION}/system/info`);
  },
  // 获取系统日志
  getSystemLogs() {
    return request.get(`${config.API_VERSION}/system/logs`);
  },
  // 创建备份
  createBackup() {
    return request.post(`${config.API_VERSION}/system/backup`);
  },
  // 恢复备份
  restoreBackup(id) {
    return request.post(`${config.API_VERSION}/system/backup/${id}/restore`);
  }
};

export default {
  serverApi,
  roomApi,
  playerApi,
  modApi,
  systemApi
};
